use std::fs;

fn rows(text: &str) -> Vec<&str> {
    text.lines().map(str::trim).filter(|line| !line.is_empty()).collect()
}

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let template = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let output = template
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", output).map_err(|_| 1)
}

pub fn gait(expected: i32, packed: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    if packed.is_empty() {
        return 1;
    }

    let mut taken = 0i32;
    let mut matched = 0i32;
    let mut probe = String::new();
    let mut valid = true;
    for (day, _) in packed {
        let name = format!("d{:08}.tbl", day);
        let source_path = format!("/app/daywell/{}", name);
        let restored_path = format!("/app/packbay/latest/{}", name);
        let source = match fs::read_to_string(&source_path) {
            Ok(text) => text,
            Err(_) => return 1,
        };
        let restored = match fs::read_to_string(&restored_path) {
            Ok(text) => text,
            Err(_) => return 1,
        };
        let source_rows = rows(&source);
        let restored_rows = rows(&restored);
        taken += source_rows.len() as i32;
        matched += source_rows
            .iter()
            .zip(restored_rows.iter())
            .filter(|(a, b)| a == b)
            .count() as i32;
        if source_rows != restored_rows {
            valid = false;
        }
        if !source_rows.is_empty() {
            probe = source_path;
        }
    }

    if probe.is_empty() {
        return 1;
    }
    if emit(&probe, matched, taken).is_err() {
        return 1;
    }
    if !valid || taken != expected || matched != taken {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
